#' Generate an overview sentence for a cancer registry ASR table
#'
#' `cr_overview()` creates an overview paragraph for one cancer and one event
#' type from an ASR table generated by `canregtools::create_asr()` followed by
#' `canregtools::add_labels()`.
#'
#' @param data A data frame with ASR columns such as `areacode`, `areacode_cn`,
#'   `year`, `sex`, `cancer`, `cancer_cn`, `no_cases`, `cr`, `asr_cn2000`,
#'   `asr_wld85`, `cumur`, `prop`, and `rank`.
#' @param cancer Cancer code, Chinese cancer label, or English cancer label.
#' @param event_type Event type. One of `"incidence"` or `"mortality"`.
#' @param area Main area code or label used for the total, male, and female
#'   rows.
#' @param area_roles A named list identifying urban and rural rows. Defaults to
#'   `list(urban = 910000, rural = 920000)`.
#' @param lang Language code. One of `"zh"` or `"en"`.
#' @param sex_specific Whether the cancer should be described without sex
#'   stratification. If `NULL`, this is inferred from sex-specific case counts.
#' @param digits Number of decimal places for rates and percentages.
#' @param ratio_digits Number of decimal places for ratios.
#' @param compare_threshold Relative threshold for treating two standardized
#'   rates as similar. Defaults to `0`, meaning any difference is classified.
#' @param output Output mode. `"text"` returns the rendered paragraph, `"data"`
#'   returns a one-row data frame of template values, and `"both"` returns both.
#'
#' @return A character string, data frame, or list, depending on `output`.
#' @export
cr_overview <- function(data,
                        cancer,
                        event_type = c("incidence", "mortality"),
                        area,
                        area_roles = list(urban = 910000, rural = 920000),
                        lang = "zh",
                        sex_specific = NULL,
                        digits = 2,
                        ratio_digits = 2,
                        compare_threshold = 0,
                        output = c("text", "data", "both")) {
  event_type <- match.arg(event_type)
  output <- .cr_check_output(output)

  if (missing(area) || is.null(area)) {
    stop("`area` must be supplied.", call. = FALSE)
  }

  .cr_validate_asr_overview_data(data)
  .cr_check_digits(digits)
  .cr_check_digits(ratio_digits, name = "ratio_digits")
  .cr_check_threshold(compare_threshold)
  lang <- match.arg(lang, c("zh", "en"))

  main_total <- .cr_pick_asr_row(data, cancer = cancer, area = area, sex = 0)
  main_male <- .cr_pick_asr_row(data, cancer = cancer, area = area, sex = 1)
  main_female <- .cr_pick_asr_row(data, cancer = cancer, area = area, sex = 2)
  urban_total <- .cr_pick_asr_row(data, cancer = cancer, area = area_roles$urban, sex = 0)
  rural_total <- .cr_pick_asr_row(data, cancer = cancer, area = area_roles$rural, sex = 0)

  if (is.null(sex_specific)) {
    sex_specific <- .cr_is_sex_specific(main_male, main_female)
  }
  sex_specific <- isTRUE(sex_specific)

  if (is.na(main_total$rank)) {
    stop(
      "`rank` is missing for this row. `cr_overview()` currently expects a specific cancer row.",
      call. = FALSE
    )
  }

  overview_template <- .cr_load_template("overview", lang = lang)
  template_key <- if (sex_specific) "sex_specific" else "default"
  template <- overview_template$overall[[template_key]]
  ratio_templates <- overview_template$ratio
  lang_data <- .cr_load_lang(lang)
  event_terms <- .cr_get_event_terms(event_type, lang = lang)

  area_status <- .cr_compare_status(
    urban_total$asr_cn2000,
    rural_total$asr_cn2000,
    left_higher = "urban_higher",
    right_higher = "rural_higher",
    similar = "similar",
    threshold = compare_threshold
  )

  sex_status <- if (sex_specific) {
    "similar"
  } else {
    .cr_compare_status(
      main_male$asr_cn2000,
      main_female$asr_cn2000,
      left_higher = "male_higher",
      right_higher = "female_higher",
      similar = "similar",
      threshold = compare_threshold
    )
  }

  sex_ratio <- if (sex_specific) {
    NA_real_
  } else {
    .cr_ratio(main_male$asr_cn2000, main_female$asr_cn2000)
  }
  area_ratio <- .cr_ratio(urban_total$asr_cn2000, rural_total$asr_cn2000)
  label_suffix <- .cr_label_suffix(lang)
  cancer_name <- .cr_label_value(main_total, "cancer", label_suffix)

  values <- list(
    year = main_total$year,
    area_name = .cr_label_value(main_total, "areacode", label_suffix),
    cancer_name = cancer_name,
    cancer_name_sentence = .cr_sentence_case_en(cancer_name),
    cancer_name_lower = tolower(cancer_name),
    event_noun = event_terms$noun,
    event_case_label = event_terms$case_label,
    event_rate_label = event_terms$rate_label,
    event_crude_rate_label = event_terms$crude_rate_label,
    event_rank_phrase = event_terms$rank_phrase,
    event_cause_label = event_terms$cause_label,
    event_total_case_phrase = event_terms$total_case_phrase,
    event_total_case_suffix = event_terms$total_case_suffix,
    sex_male = lang_data$sex$male,
    sex_female = lang_data$sex$female,
    area_urban = lang_data$area$urban,
    area_rural = lang_data$area$rural,
    area_urban_full = lang_data$area$urban_full,
    area_rural_full = lang_data$area$rural_full,
    phrase_registration_area = lang_data$phrase$registration_area,
    phrase_cancer_spectrum = lang_data$phrase$cancer_spectrum,
    phrase_all_cancers = lang_data$phrase$all_cancers,
    phrase_per_100000 = lang_data$phrase$per_100000,
    phrase_asr_china = lang_data$phrase$asr_china,
    phrase_asr_world = lang_data$phrase$asr_world,
    phrase_cumulative_0_74 = lang_data$phrase$cumulative_0_74,
    no_cases = .cr_format_number(main_total$no_cases, digits = 0),
    male_cases = .cr_format_number(main_male$no_cases, digits = 0),
    female_cases = .cr_format_number(main_female$no_cases, digits = 0),
    urban_cases = .cr_format_number(urban_total$no_cases, digits = 0),
    rural_cases = .cr_format_number(rural_total$no_cases, digits = 0),
    prop = .cr_format_number(main_total$prop, digits = digits),
    cr = .cr_format_number(main_total$cr, digits = digits),
    asr_cn2000 = .cr_format_number(main_total$asr_cn2000, digits = digits),
    asr_wld85 = .cr_format_number(main_total$asr_wld85, digits = digits),
    cumur = .cr_format_number(main_total$cumur, digits = digits),
    male_cr = .cr_format_number(main_male$cr, digits = digits),
    female_cr = .cr_format_number(main_female$cr, digits = digits),
    urban_cr = .cr_format_number(urban_total$cr, digits = digits),
    rural_cr = .cr_format_number(rural_total$cr, digits = digits),
    sex_compare_text = lang_data$sex[[sex_status]],
    area_compare_text = lang_data$area[[area_status]],
    sex_ratio = .cr_format_number(sex_ratio, digits = ratio_digits),
    area_ratio = .cr_format_number(area_ratio, digits = ratio_digits),
    rank = main_total$rank,
    rank_ordinal = .cr_ordinal_en(main_total$rank)
  )

  values$sex_ratio_text <- .cr_render_text(ratio_templates$sex[[sex_status]], values)
  values$area_ratio_text <- .cr_render_text(ratio_templates$area[[area_status]], values)

  text <- .cr_render_text(template, values)
  .cr_output_result(text, values, output = output)
}

.cr_validate_asr_overview_data <- function(data) {
  required <- c(
    "areacode", "areacode_en", "areacode_cn", "year", "sex", "cancer",
    "cancer_en", "cancer_cn", "no_cases", "cr", "asr_cn2000",
    "asr_wld85", "cumur", "prop", "rank"
  )

  .cr_check_required_columns(data, required)

  invisible(data)
}

.cr_pick_asr_row <- function(data, cancer, area, sex) {
  cancer_values <- as.character(cancer)
  area_values <- as.character(area)

  row <- data[
    as.character(data$sex) == as.character(sex) &
      (
        as.character(data$cancer) %in% cancer_values |
          as.character(data$cancer_cn) %in% cancer_values |
          as.character(data$cancer_en) %in% cancer_values
      ) &
      (
        as.character(data$areacode) %in% area_values |
          as.character(data$areacode_cn) %in% area_values |
          as.character(data$areacode_en) %in% area_values
      ),
    ,
    drop = FALSE
  ]

  if (nrow(row) == 0L) {
    stop(
      "No ASR row found for the requested cancer, area, and sex.",
      call. = FALSE
    )
  }

  if (nrow(row) > 1L) {
    stop(
      "Multiple ASR rows found for the requested cancer, area, and sex.",
      call. = FALSE
    )
  }

  row
}

.cr_is_sex_specific <- function(male_row, female_row) {
  isTRUE(male_row$no_cases == 0) || isTRUE(female_row$no_cases == 0)
}
